from __future__ import annotations


def build_data_center_ui() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>数据中心 V3.23</title>
<style>body{margin:0;background:#0b1020;color:#dbeafe;font-family:Segoe UI,Microsoft YaHei,Arial,sans-serif}header{height:58px;display:flex;align-items:center;gap:12px;padding:0 18px;background:#101827;border-bottom:1px solid #283956}.brand{font-weight:900;font-size:20px;color:#bfdbfe}.grow{flex:1}a{color:#bfdbfe}main{padding:14px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.panel{background:#111827;border:1px solid #26364f;border-radius:14px;overflow:hidden}.h{padding:12px;background:#141f35;border-bottom:1px solid #26364f;font-weight:900}.b{padding:12px}pre{white-space:pre-wrap;word-break:break-word}.muted{color:#91a7c7}button{border:0;border-radius:10px;background:#2563eb;color:#fff;padding:9px 12px;font-weight:800}</style></head><body><header><div class="brand">数据中心 V3.23</div><span class="muted">真实数据、缓存、缺失字段、券商状态</span><div class="grow"></div><a href="/screener">筛选</a><a href="/ui">行情</a><a href="/live-trading">真实交易</a></header><main><section class="panel"><div class="h">总览</div><div class="b"><button onclick="load()">刷新</button><pre id="status">Loading...</pre></div></section><section class="panel"><div class="h">缺失字段</div><div class="b"><pre id="missing">Loading...</pre></div></section><section class="panel"><div class="h">错误/数据源</div><div class="b"><pre id="errors">Loading...</pre></div></section></main><script>
async function load(){const a=await fetch('/api/data-center/status').then(r=>r.json());const b=await fetch('/api/data-center/missing-fields').then(r=>r.json());const c=await fetch('/api/data-center/source-errors').then(r=>r.json());status.textContent=JSON.stringify(a,null,2);missing.textContent=JSON.stringify(b,null,2);errors.textContent=JSON.stringify(c,null,2)}load()
</script></body></html>"""
